3	import java.time.LocalDate;
4	import java.time.temporal.ChronoUnit;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Derives an owner's membership level from its profile completeness and its tenure.
10	 *
11	 * <p>The level starts at 1 and gains a point for each maxed pre-tenure factor: a contactable email,
12	 * a unique name ({@code namesakeCount} of 0) and belonging to a household of three or more members.
13	 * These factors alone can reach level 3.
14	 *
15	 * <p>Level 4 is a loyalty tier: it additionally requires a tenure of more than 365 days since the
16	 * owner's registration date. Because a newly created owner has zero tenure, a new owner never
17	 * exceeds level 3 — even one whose pre-tenure factors are all maxed lands at 3, not 4.
18	 *
19	 * <p>Kept as a standalone helper (rather than a method on {@link OwnerMapper}) so MapStruct does not
20	 * mistake it for a mapping method and apply it to unrelated fields.
21	 */
22	public final class MembershipLevel {
23	
24	    private MembershipLevel() {
25	    }
26	
27	    /**
28	     * The membership level of {@code owner}: 1-3 from its pre-tenure factors, capped at 3 unless the
29	     * owner has more than 365 days of tenure, in which case level 4 is attainable.
30	     */
31	    public static int of(Owner owner) {
32	        int level = 1;
33	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
34	            level++;
35	        }
36	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
37	            level++;
38	        }
39	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
40	            level++;
41	        }
42	        int cap = tenureDays(owner) > 365 ? 4 : 3;
43	        return Math.min(cap, level);
44	    }
45	
46	    private static long tenureDays(Owner owner) {
47	        LocalDate registrationDate = owner.getRegistrationDate();
48	        if (registrationDate == null) {
49	            return 0;
50	        }
51	        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
52	    }
53	}
